export const projectPlanLocales = Object.fromEntries(Object.entries(values).map(([lang, strings]) => [lang, Object.fromEntries(keys.map((key, i) => [key, strings[i]]))]))
const extra = {
  zh: ['视图', '甘特图', '已另存并重新读取验证。格式转换可能丢失原软件特有字段；请在 Project/P6 中复核日历、依赖、资源及基线。'],
  en: ['View', 'Gantt chart', 'Saved and verified by reopening. Conversion may lose source-specific fields; review calendars, dependencies, resources and baselines in Project/P6.'],
  es: ['Vista', 'Diagrama de Gantt', 'Guardado y verificado al volver a abrir. La conversión puede perder campos específicos; revise calendarios, dependencias, recursos y líneas base en Project/P6.'],
  fr: ['Vue', 'Diagramme de Gantt', 'Enregistré et vérifié par relecture. La conversion peut perdre des champs spécifiques ; vérifiez calendriers, dépendances, ressources et références dans Project/P6.'],
  de: ['Ansicht', 'Gantt-Diagramm', 'Gespeichert und durch erneutes Lesen geprüft. Formatspezifische Felder können verloren gehen; Kalender, Abhängigkeiten, Ressourcen und Basispläne in Project/P6 prüfen.'],
  ja: ['表示', 'ガントチャート', '保存後に再読み込みして検証済みです。変換で固有の項目が失われる場合があります。Project/P6 でカレンダー、依存関係、リソース、基準計画を確認してください。'],
  ko: ['보기', '간트 차트', '저장 후 다시 읽어 검증했습니다. 변환 시 고유 필드가 손실될 수 있으므로 Project/P6에서 달력, 선후행 관계, 자원, 기준선을 확인하세요.'],
  pt: ['Visualização', 'Gráfico de Gantt', 'Salvo e verificado por releitura. A conversão pode perder campos específicos; revise calendários, dependências, recursos e linhas de base no Project/P6.'],
  ru: ['Вид', 'Диаграмма Ганта', 'Файл сохранён и проверен повторным чтением. При преобразовании могут потеряться специфические поля; проверьте календари, связи, ресурсы и базовые планы в Project/P6.'],
  ar: ['العرض', 'مخطط جانت', 'تم الحفظ والتحقق بإعادة القراءة. قد تفقد عملية التحويل حقولًا خاصة؛ راجع التقويمات والعلاقات والموارد والخطط الأساسية في Project/P6.'],
}
for (const [lang, [view, gantt, exportWarning]] of Object.entries(extra)) Object.assign(projectPlanLocales[lang], { view, gantt, exportWarning })
export function planTranslator(lang) { return key => projectPlanLocales[lang]?.[key] || projectPlanLocales.en[key] || key }
